{"implementation":"def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required = payload['required_symbols']
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
        else:
            children[n['parent']].append(n['id'])
    # compute descendants for each node
    def _descendants(nid):
        res = {nid}
        for c in children[nid]:
            res |= _descendants(c)
        return res
    descendants = {nid: _descendants(nid) for nid in node_by_id}
    # symbol to node ids
    sym_to_ids = {}
    for n in nodes:
        sym_to_ids.setdefault(n['symbol'], []).append(n['id'])
    # validate required symbols exist
    for s in required:
        if s not in sym_to_ids or not sym_to_ids[s]:
            raise ValueError('Required symbol missing')
    # sort by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = set()
    removal_order = []
    for node in sorted_nodes:
        nid = node['id']
        if nid == root_id:
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required:
            continue
        # retained children check
        if any(c not in removed for c in children[nid]):
            continue
        # check required symbols after removal of this subtree
        subtree = descendants[nid]
        feasible = True
        for s in required:
            found = False
            for cand in sym_to_ids[s]:
                if cand not in removed and cand not in subtree:
                    found = True
                    break
            if not found:
                feasible = False
                break
        if not feasible:
            continue
        removed.add(nid)
        removal_order.append(nid)
    retained = [nid for nid in node_by_id if nid not in removed]
    retained.sort()
    return {'retained_ids': retained, 'removal_order': removal_order}"}
